package com.example.reportservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.util.UUID

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    routing {
        post("/api/v1/reports/generate") {
            val contentType = call.request.contentType()
            val body = call.receiveText()
            val reportId = call.request.queryParameters["report_id"] ?: UUID.randomUUID().toString()

            // Generate temporary file for intermediate processing
            val tempDir = System.getProperty("java.io.tmpdir")
            val tempFile = File("$tempDir/report_$reportId.tmp")

            try {
                // Write report data to temp file for async processing
                tempFile.writeText(body)

                // Set permissions (attempt at hardening, but race window exists)
                tempFile.setReadable(false, false)
                tempFile.setReadable(true, true)
                tempFile.setWritable(false, false)
                tempFile.setWritable(true, true)

                // Simulate report generation pipeline
                val result = processReport(tempFile, reportId)

                call.respondText(result, ContentType.Application.Json, HttpStatusCode.OK)
            } finally {
                // Cleanup
                tempFile.delete()
            }
        }

        get("/api/v1/reports/{id}/status") {
            val id = call.parameters["id"] ?: ""
            val tempDir = System.getProperty("java.io.tmpdir")
            val tempFile = File("$tempDir/report_$id.tmp")

            if (tempFile.exists()) {
                call.respondText(
                    """{"status": "processing", "id": "$id"}""",
                    ContentType.Application.Json
                )
            } else {
                call.respondText(
                    """{"status": "completed", "id": "$id"}""",
                    ContentType.Application.Json
                )
            }
        }

        get("/health") {
            call.respondText("OK")
        }
    }
}

fun processReport(tempFile: File, reportId: String): String {
    // Read back and transform
    val content = tempFile.readText()
    val lineCount = content.lines().size
    val wordCount = content.split("\\s+".toRegex()).size

    // Secondary temp file for transformed output
    val tempDir = System.getProperty("java.io.tmpdir")
    val outputFile = File("$tempDir/report_${reportId}_output.tmp")

    try {
        outputFile.writeText("""{"report_id": "$reportId", "lines": $lineCount, "words": $wordCount, "status": "generated"}""")
        return outputFile.readText()
    } finally {
        outputFile.delete()
    }
}
